// ---------------------------------------------------------------- helpers
const CENTER = ["center at 50vw", "middle at 45vh"];
const WORD_CSS = {"font-size": CFG.fontSize, "white-space": "nowrap"};

// Fixation cross, then the sentence word by word in place.
// Like legacy DashedSentence 'in place': each word for wordTime ms, a blank screen
// of pauseTime ms between words, and the question right after the last word.
function rsvp(sentence) {
    const words = sentence.trim().split(/\s+/);
    const cmds = [
        newText("fix", "+").css(WORD_CSS).print(...CENTER),
        newTimer("fixT", CFG.fixationTime).start().wait(),
        getText("fix").remove()
    ];
    words.forEach((w, i) => {
        cmds.push(
            newText("w" + i, w).css(WORD_CSS).print(...CENTER),
            newTimer("wT" + i, CFG.wordTime).start().wait(),
            getText("w" + i).remove()
        );
        if (i < words.length - 1 && CFG.pauseTime > 0)
            cmds.push(newTimer("pT" + i, CFG.pauseTime).start().wait());
    });
    return cmds;
}

// Yes/No judgment under a deadline. Logs response (yes/no/NA), RT (ms from question
// onset; NA on timeout) and timedout (yes/no). Keys or mouse clicks both work.
function judgment() {
    return [
        newVar("response", "NA").global(),   // global so the trial can .log() them
        newVar("RT", "NA").global(),
        newVar("timedout", "no").global(),
        getVar("response").set("NA"), getVar("RT").set("NA"), getVar("timedout").set("no"),   // reset per trial
        newTimer("deadline", CFG.deadline),
        newText("question", CFG.question).css({"font-size": CFG.fontSize}),
        newText("yes", CFG.yesLabel).css({"font-size": CFG.fontSize, "cursor": "pointer"}),
        newText("no", CFG.noLabel).css({"font-size": CFG.fontSize, "cursor": "pointer"}),
        newText("keyhint", CFG.keyHint).css({"font-size": "1em", "color": "#666"}),
        newCanvas("answer", 600, 220)
            .add("center at 50%", 0, getText("question"))
            .add("center at 25%", 90, getText("yes"))
            .add("center at 75%", 90, getText("no"))
            .add("center at 50%", 170, getText("keyhint"))
            .print("center at 50vw", "top at 35vh"),
        newSelector("judgment")
            .add(getText("yes"), getText("no"))
            .keys(CFG.yesKey, CFG.noKey)
            .once()
            .log()
            .callback(
                getVar("RT").set(v => Date.now() - v),
                getTimer("deadline").stop()
            ),
        getVar("RT").set(v => Date.now()),
        getTimer("deadline").start().wait(),
        getSelector("judgment").disable(),   // no late answers after the deadline
        getSelector("judgment")
            .test.selected(getText("yes"))
            .success(getVar("response").set("yes"))
            .failure(
                getSelector("judgment").test.selected(getText("no"))
                    .success(getVar("response").set("no"))
                    .failure(
                        getVar("timedout").set("yes"),
                        getVar("RT").set("NA"),
                        getCanvas("answer").remove(),
                        newText("timeoutMsg", CFG.timeoutMessage).css({"font-size": "1.5em"}).print(...CENTER),
                        newTimer("timeoutT", CFG.timeoutMessageTime).start().wait()
                    )
            ),
        getCanvas("answer").remove()
    ];
}

// A judgment trial; logs the per-row columns named in `cols` plus the response vars.
function judgmentTrial(label, row, cols) {
    let t = newTrial(label, ...rsvp(row[CFG.sentenceColumn]), ...judgment())
        .log("response", getVar("response"))
        .log("RT", getVar("RT"))
        .log("timedout", getVar("timedout"));
    cols.forEach(c => { t = t.log(c, row[c]); });
    return t;
}

// An HTML form page that must be completed (class="obligatory" fields) before going on.
function formPage(label, file) {
    return newTrial(label,
        newHtml("form", file).log().print(),
        newButton("continue", "Continue").css({"margin": "1em"}).center().print()
            .wait(getHtml("form").test.complete().failure(getHtml("form").warn()))
    );
}

function message(label, html, buttonText) {
    return newTrial(label,
        newText("msg", html).css({"font-size": "1.2em", "max-width": "40em"}).center().print(),
        newButton("continue", buttonText || "Continue").css({"margin": "1em"}).center().print().wait()
    );
}

